{
  "name": "claw-multi-agent",
  "version": "1.0.0",
  "description": "Claw Multi Agent enables parallel multi-agent orchestration for comprehensive research, model comparison, and code pipelines. Each agent runs in an isolated session — built-in context injection keeps the team aligned without the token overhead.",
  "keywords": ["openclaw", "skill", "multi-agent", "swarm", "orchestration", "parallel", "token-efficient", "research", "pipeline"],
  "author": "",
  "license": "MIT",
  "openclaw": {
    "skill": true,
    "entrypoint": "SKILL.md"
  }
}

{
  "name": "多维代码审查",
  "description": "从安全、性能、可读性三个维度并行审查代码。使用时请将 {file_path} 替换为实际文件路径（仅限项目内文件）。",
  "_security_note": "file_path should be a relative path within the user's project. Never use absolute paths or paths outside the working directory.",
  "phases": [
    {
      "name": "并行审查",
      "mode": "parallel",
      "aggregation": "compare",
      "agents": [
        {
          "task": "请审查以下代码文件的【安全性】问题，包括：注入漏洞、认证缺陷、敏感信息泄露。\n\n代码路径（项目内相对路径）：{file_path}\n\n请逐条列出问题（严重/高/中/低），并给出修复建议。",
          "model": "opus",
          "role": "安全专家",
          "label": "security-review"
        },
        {
          "task": "请审查以下代码文件的【性能】问题，包括：算法复杂度、数据库查询、内存使用、并发问题。\n\n代码路径（项目内相对路径）：{file_path}\n\n请逐条列出性能瓶颈并给出优化建议。",
          "model": "kimi",
          "role": "性能工程师",
          "label": "performance-review"
        },
        {
          "task": "请审查以下代码文件的【代码质量】，包括：命名规范、注释完整性、模块化、可测试性。\n\n代码路径（项目内相对路径）：{file_path}\n\n请逐条给出改进建议。",
          "model": "claude",
          "role": "代码审查员",
          "label": "quality-review"
        }
      ]
    }
  ]
}

{
  "name": "多模型对比",
  "description": "向多个模型发送同一问题，对比回答质量",
  "phases": [
    {
      "name": "多模型回答",
      "mode": "parallel",
      "aggregation": "compare",
      "agents": [
        {
          "task": "{prompt}",
          "model": "kimi",
          "role": "AI助手",
          "label": "kimi"
        },
        {
          "task": "{prompt}",
          "model": "claude",
          "role": "AI助手",
          "label": "claude-sonnet"
        },
        {
          "task": "{prompt}",
          "model": "gemini",
          "role": "AI助手",
          "label": "gemini-pro"
        },
        {
          "task": "{prompt}",
          "model": "glm",
          "role": "AI助手",
          "label": "glm-5"
        }
      ]
    }
  ]
}

{
  "name": "并行调研报告",
  "description": "并行调研多个主题，然后综合成报告",
  "phases": [
    {
      "name": "并行调研",
      "mode": "parallel",
      "aggregation": "synthesize",
      "agents": [
        {
          "task": "调研 LangChain 框架：架构、优缺点、适用场景、最新动态。输出结构化 Markdown。",
          "model": "kimi",
          "role": "研究员",
          "label": "research-langchain"
        },
        {
          "task": "调研 CrewAI 框架：架构、优缺点、适用场景、最新动态。输出结构化 Markdown。",
          "model": "glm",
          "role": "研究员",
          "label": "research-crewai"
        },
        {
          "task": "调研 AutoGen 框架：架构、优缺点、适用场景、最新动态。输出结构化 Markdown。",
          "model": "gemini",
          "role": "研究员",
          "label": "research-autogen"
        }
      ]
    },
    {
      "name": "综合报告",
      "mode": "sequential",
      "aggregation": "last",
      "depends_on": ["并行调研"],
      "agents": [
        {
          "task": "基于以上3个框架的调研结果，撰写一篇完整的对比分析报告。包含：总结表格、各框架详细分析、选型建议。",
          "model": "claude",
          "role": "技术写作者",
          "label": "final-report"
        }
      ]
    }
  ]
}
